/**
 * Templates: categories of businesses and, for each one, the templates generated by the AI.
 * Saved templates are reused by every project of the category (Template step of the wizard).
 */
import { useEffect, useMemo, useState } from 'react';
import { Copy, FileText, FolderPlus, LayoutTemplate, Pencil, Sparkles, Trash2 } from 'lucide-react';
import { api } from '../api.js';
import { useT } from '../i18n/index.jsx';
import { useToast } from '../components/Toast.jsx';
import { Button, Card, EmptyState, Field, IconButton, Input, Modal, PageHeader, Spinner, Textarea, cx } from '../components/ui.jsx';
import { TemplatePreview, TemplateSwatches } from '../components/TemplatePreview.jsx';
import { TemplateEditor, TemplateGenerator } from '../components/TemplateDialogs.jsx';
import { IndustryProfile } from '../components/IndustryProfile.jsx';
import { formatDate } from './ProjectsPage.jsx';

export default function TemplatesPage() {
  const { t } = useT();
  const toast = useToast();
  const [categories, setCategories] = useState(null);
  const [selectedId, setSelectedId] = useState(null);
  const [templates, setTemplates] = useState(null);
  const [newName, setNewName] = useState('');
  const [editingCategory, setEditingCategory] = useState(null); // { id, name, description }
  const [catToDelete, setCatToDelete] = useState(null);
  const [generating, setGenerating] = useState(false);
  const [editing, setEditing] = useState(null);
  const [toDelete, setToDelete] = useState(null);
  const [prompt, setPrompt] = useState(null);

  const loadCategories = () =>
    api.get('/template-categories').then((list) => {
      setCategories(list);
      setSelectedId((id) => (list.some((c) => c.id === id) ? id : list[0]?.id ?? null));
      return list;
    });
  const loadTemplates = (categoryId) => (categoryId ? api.get(`/templates?category=${categoryId}`).then(setTemplates) : setTemplates([]));

  useEffect(() => {
    loadCategories().catch((e) => toast(e.message, 'error'));
  }, []); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => {
    setTemplates(null);
    loadTemplates(selectedId)?.catch?.((e) => toast(e.message, 'error'));
  }, [selectedId]); // eslint-disable-line react-hooks/exhaustive-deps

  const selected = useMemo(() => categories?.find((c) => c.id === selectedId) || null, [categories, selectedId]);
  const refresh = () => Promise.all([loadCategories(), loadTemplates(selectedId)]).catch((e) => toast(e.message, 'error'));

  const addCategory = async (e) => {
    e.preventDefault();
    try {
      const cat = await api.post('/template-categories', { name: newName });
      setNewName('');
      await loadCategories();
      setSelectedId(cat.id);
    } catch (err) {
      toast(err.message, 'error');
    }
  };

  const saveCategory = async () => {
    try {
      await api.patch(`/template-categories/${editingCategory.id}`, { name: editingCategory.name, description: editingCategory.description });
      setEditingCategory(null);
      loadCategories();
    } catch (e) {
      toast(e.message, 'error');
    }
  };

  const deleteCategory = async () => {
    const cat = catToDelete;
    setCatToDelete(null);
    try {
      await api.del(`/template-categories/${cat.id}`);
      toast(t('Category deleted'));
      loadCategories();
    } catch (e) {
      toast(e.message, 'error');
    }
  };

  const duplicate = async (tpl) => {
    try {
      await api.post(`/templates/${tpl.id}/duplicate`);
      refresh();
    } catch (e) {
      toast(e.message, 'error');
    }
  };

  const removeTemplate = async () => {
    const tpl = toDelete;
    setToDelete(null);
    try {
      await api.del(`/templates/${tpl.id}`);
      toast(t('Template deleted'));
      refresh();
    } catch (e) {
      toast(e.message, 'error');
    }
  };

  const showPrompt = () => api.get('/prompts/template').then(setPrompt).catch((e) => toast(e.message, 'error'));

  if (!categories) {
    return (
      <div className="flex justify-center py-20">
        <Spinner />
      </div>
    );
  }

  return (
    <>
      <PageHeader
        title={t('Templates')}
        description={t('Create a category for each kind of business, let the AI design templates for it and save them: every project of that category can reuse them.')}
        actions={
          <Button variant="ghost" icon={FileText} onClick={showPrompt}>
            {t('Show the prompt')}
          </Button>
        }
      />

      <div className="grid gap-6 lg:grid-cols-[260px_1fr]">
        <Card title={t('Categories')} className="self-start" padded={false}>
          <nav className="space-y-0.5 p-2">
            {!categories.length && <p className="px-3 py-2 text-sm text-slate-500">{t('No categories yet.')}</p>}
            {categories.map((c) => (
              <div key={c.id} className="group relative">
                <button
                  type="button"
                  onClick={() => setSelectedId(c.id)}
                  className={cx(
                    'flex w-full items-center justify-between gap-2 rounded-lg px-3 py-2 text-left text-sm',
                    c.id === selectedId ? 'bg-brand-50 font-medium text-brand-700' : 'text-slate-700 hover:bg-slate-100'
                  )}
                >
                  <span className="truncate">{c.name}</span>
                  <span className={cx('text-xs tabular-nums', c.id === selectedId ? 'text-brand-600' : 'text-slate-400')}>{c.template_count}</span>
                </button>
                <div className="absolute top-1/2 right-9 hidden -translate-y-1/2 gap-0.5 group-focus-within:flex group-hover:flex">
                  <IconButton icon={Pencil} label={t('Edit')} onClick={() => setEditingCategory({ id: c.id, name: c.name, description: c.description })} className="size-7 bg-white" />
                  <IconButton icon={Trash2} label={t('Delete')} onClick={() => setCatToDelete(c)} className="size-7 bg-white hover:text-red-600" />
                </div>
              </div>
            ))}
          </nav>
          <form onSubmit={addCategory} className="flex gap-2 border-t border-slate-100 p-3">
            <Input value={newName} onChange={(e) => setNewName(e.target.value)} placeholder={t('New category (e.g. Plumbers)')} aria-label={t('New category')} maxLength={80} className="min-w-0 flex-1" />
            <Button type="submit" icon={FolderPlus} disabled={!newName.trim()} aria-label={t('Add category')} title={t('Add category')} />
          </form>
        </Card>

        {!selected ? (
          <EmptyState icon={LayoutTemplate} title={t('Create your first category')} description={t('For example "Plumbers", "Restaurants" or "Dentists". Then generate one or more templates for it.')} />
        ) : (
          <Card
            title={selected.name}
            description={selected.description || t('No description: add one to help the AI design for this category.')}
            actions={
              <>
                <Button size="sm" icon={Pencil} onClick={() => setEditingCategory({ id: selected.id, name: selected.name, description: selected.description })}>
                  {t('Edit category')}
                </Button>
                <Button size="sm" variant="primary" icon={Sparkles} onClick={() => setGenerating(true)}>
                  {t('Generate template')}
                </Button>
              </>
            }
          >
            <IndustryProfile category={selected} onAnalyzed={loadCategories} />
            {!templates ? (
              <div className="flex justify-center py-10">
                <Spinner />
              </div>
            ) : !templates.length ? (
              <EmptyState
                icon={LayoutTemplate}
                title={t('No templates in this category')}
                description={t('Generate a template with the AI: you can preview it, regenerate it and save it.')}
                action={
                  <Button variant="primary" icon={Sparkles} onClick={() => setGenerating(true)}>
                    {t('Generate template')}
                  </Button>
                }
              />
            ) : (
              <ul className="grid gap-5 md:grid-cols-2">
                {templates.map((tpl) => (
                  <li key={tpl.id} className="overflow-hidden rounded-xl border border-slate-200">
                    <TemplatePreview spec={tpl.spec} compact className="rounded-none border-0 border-b" />
                    <div className="space-y-2 p-3">
                      <div className="flex items-start justify-between gap-2">
                        <div className="min-w-0">
                          <p className="truncate font-medium text-slate-900">{tpl.name}</p>
                          <p className="text-xs text-slate-500">
                            {formatDate(tpl.created_at)} · {t('used by {n} project(s)', { n: tpl.used_by })}
                          </p>
                        </div>
                        <div className="flex shrink-0 gap-0.5">
                          <IconButton icon={Pencil} label={t('Edit')} onClick={() => setEditing(tpl)} />
                          <IconButton icon={Copy} label={t('Duplicate')} onClick={() => duplicate(tpl)} />
                          <IconButton icon={Trash2} label={t('Delete')} onClick={() => setToDelete(tpl)} className="hover:text-red-600" />
                        </div>
                      </div>
                      <TemplateSwatches spec={tpl.spec} direction={tpl.direction_name && t(tpl.direction_name)} />
                    </div>
                  </li>
                ))}
              </ul>
            )}
          </Card>
        )}
      </div>

      <TemplateGenerator open={generating} onClose={() => setGenerating(false)} category={selected} onSaved={refresh} onAnalyzed={loadCategories} />
      <TemplateEditor template={editing} onClose={() => setEditing(null)} onSaved={refresh} />

      <Modal
        open={!!editingCategory}
        onClose={() => setEditingCategory(null)}
        title={t('Edit category')}
        footer={
          <>
            <Button onClick={() => setEditingCategory(null)}>{t('Cancel')}</Button>
            <Button variant="primary" onClick={saveCategory} disabled={!editingCategory?.name.trim()}>
              {t('Save')}
            </Button>
          </>
        }
      >
        {editingCategory && (
          <div className="space-y-4">
            <Field label={t('Category name')}>{(id) => <Input id={id} value={editingCategory.name} onChange={(e) => setEditingCategory({ ...editingCategory, name: e.target.value })} maxLength={80} />}</Field>
            <Field label={t('Description')} hint={t('What the businesses of this category do and who their customers are. Sent to the AI when it designs a template.')}>
              {(id) => <Textarea id={id} rows={4} value={editingCategory.description} onChange={(e) => setEditingCategory({ ...editingCategory, description: e.target.value })} maxLength={1000} />}
            </Field>
          </div>
        )}
      </Modal>

      <Modal
        open={!!catToDelete}
        onClose={() => setCatToDelete(null)}
        title={t('Delete category?')}
        size="sm"
        footer={
          <>
            <Button onClick={() => setCatToDelete(null)}>{t('Cancel')}</Button>
            <Button variant="danger" icon={Trash2} onClick={deleteCategory}>
              {t('Delete')}
            </Button>
          </>
        }
      >
        <p className="text-sm text-slate-600">
          {t('The category "{name}" and its {n} template(s) will be deleted.', { name: catToDelete?.name, n: catToDelete?.template_count || 0 })}
          {catToDelete?.project_count > 0 && ` ${t('{n} project(s) use them and will need another template.', { n: catToDelete.project_count })}`}
        </p>
      </Modal>

      <Modal
        open={!!toDelete}
        onClose={() => setToDelete(null)}
        title={t('Delete template?')}
        size="sm"
        footer={
          <>
            <Button onClick={() => setToDelete(null)}>{t('Cancel')}</Button>
            <Button variant="danger" icon={Trash2} onClick={removeTemplate}>
              {t('Delete')}
            </Button>
          </>
        }
      >
        <p className="text-sm text-slate-600">
          {t('The template "{name}" will be deleted.', { name: toDelete?.name })}
          {toDelete?.used_by > 0 && ` ${t('{n} project(s) use it and will need another template.', { n: toDelete.used_by })}`}
        </p>
      </Modal>

      <Modal open={!!prompt} onClose={() => setPrompt(null)} title={`${t('Prompt')}: ${prompt?.name || ''}`} size="xl">
        <p className="mb-3 text-sm text-slate-600">{t('Built-in prompt used to design every template (read-only). The generator adds the allowed fonts, icons and layouts and asks for a JSON answer.')}</p>
        <pre className="rounded-lg bg-slate-900 p-4 text-xs leading-relaxed whitespace-pre-wrap text-slate-100">{prompt?.content}</pre>
      </Modal>
    </>
  );
}
